window.RA_DATA.lines = [
  { id: "usmd-1", book_id: "moby-dick", place_ids: ["new-bedford"], location: "Chapter 7, The Chapel", location_zh: "第7章：礼拜堂", text_en: "In this same New Bedford there stands a Whaleman's Chapel, and few are the moody fishermen, shortly bound for the Indian Ocean or Pacific, who fail to make a Sunday visit to the spot. I am sure that I did not.", text_zh: "在这同一座新贝德福德城里，有一座捕鲸人的礼拜堂；那些即将驶往印度洋或太平洋、心事重重的渔人，很少有谁不在星期天来此一访。我知道自己也没有错过。", highlight_en: ["New Bedford"], translation: "original", status: "draft", checked: "Project Gutenberg #2701, 2026-11-11" },
  { id: "usmd-2", book_id: "moby-dick", place_ids: ["nantucket-island"], location: "Chapter 14, Nantucket", location_zh: "第14章：楠塔基特", text_en: "Nantucket! Take out your map and look at it. See what a real corner of the world it occupies; how it stands there, away off shore, more lonely than the Eddystone lighthouse. Look at it—a mere hillock, and elbow of sand; all beach, without a background.", text_zh: "楠塔基特！拿出地图看看吧。看它占据了世界怎样偏僻的一角；它远离海岸，比埃迪斯通灯塔还孤独。瞧，它不过是一个小沙丘、一块弯曲的沙地，尽是海滩，后面再无陆地。", highlight_en: ["Nantucket"], translation: "original", status: "draft", checked: "Project Gutenberg #2701, 2026-11-11" },
  { id: "uswal-1", book_id: "walden", place_ids: ["walden-pond"], location: "Economy", location_zh: "经济篇", text_en: "When I wrote the following pages, or rather the bulk of them, I lived alone, in the woods, a mile from any neighbor, in a house which I had built myself, on the shore of Walden Pond, in Concord, Massachusetts, and earned my living by the labor of my hands only. I lived there two years and two months.", text_zh: "我写下后面这些文字，或者说其中的大部分时，独自住在树林里，离最近的邻居一英里，住的是自己搭建的房屋，坐落在马萨诸塞州康科德的瓦尔登湖畔，完全靠双手劳动谋生。我在那里住了两年两个月。", highlight_en: ["Walden Pond"], translation: "original", status: "draft", checked: "Project Gutenberg #205, 2026-11-11" },
  { id: "ussd-1", book_id: "specimen-days", place_ids: ["washington-whitman"], location: "Back to Washington", location_zh: "重返华盛顿", text_en: "I am now remaining in and around Washington, daily visiting the hospitals. Am much in Patent-office, Eighth street, H street, Armory-square, and others. Am now able to do a little good, having money, (as almoner of others home,) and getting experience.", text_zh: "我现在留在华盛顿及周边，每天探望医院。我常去专利局、第八街、H街、军械库广场及其他医院。如今手头有些钱，替家乡的朋友施助，也渐有经验，能够做一点好事了。", highlight_en: ["Washington"], translation: "original", status: "draft", checked: "Project Gutenberg #8813, 2026-11-11" },
  { id: "ussd-2", book_id: "specimen-days", place_ids: ["falmouth-whitman"], location: "Back to Washington", location_zh: "重返华盛顿", text_en: "January, '63.—Left camp at Falmouth, with some wounded, a few days since, and came here by Aquia creek railroad, and so on government steamer up the Potomac. Many wounded were with us on the cars and boat.", text_zh: "一八六三年一月。几天前，我与一些伤兵离开法尔茅斯军营，乘阿奎亚溪铁路，再转乘政府轮船沿波托马克河来到这里。火车和船上都有许多伤兵与我们同行。", highlight_en: ["Falmouth"], translation: "original", status: "draft", checked: "Project Gutenberg #8813, 2026-11-11" },
  { id: "ussd-3", book_id: "specimen-days", place_ids: ["camden-whitman"], location: "An Ossianic Night—Dearest Friends", location_zh: "奥西安式的夜晚——最亲爱的朋友", text_en: "Nov., '81.—Again back in Camden. As I cross the Delaware in long trips tonight, between 9 and 11, the scene overhead is a peculiar one—swift sheets of flitting vapor-gauze, follow'd by dense clouds throwing an inky pall on everything.", text_zh: "一八八一年十一月。又回到了卡姆登。今晚九点至十一点，我长时间横渡特拉华河，头顶的景象十分奇特：薄纱似的雾气飞快掠过，后面跟着浓云，给一切罩上漆黑的帷幕。", highlight_en: ["Camden"], translation: "original", status: "draft", checked: "Project Gutenberg #8813, 2026-11-11" },
  { id: "ussd-4", book_id: "specimen-days", place_ids: ["pittsburgh-whitman"], location: "Begin a Long Jaunt West", location_zh: "开始向西的长途旅行", text_en: "Oblivious of the two or three hundred miles across Pennsylvania; at Pittsburgh in the morning to breakfast. Pretty good view of the city and Birmingham—fog and damp, smoke, coke-furnaces, flames, discolor'd wooden houses, and vast collections of coal-barges.", text_zh: "横穿宾夕法尼亚两三百英里的路程，不知不觉便过去了；早晨抵达匹兹堡吃早餐。城市与伯明翰区尽收眼底：雾气与湿气、烟雾、炼焦炉、火焰、变色的木屋，还有大批运煤驳船。", highlight_en: ["Pittsburgh"], translation: "original", status: "draft", checked: "Project Gutenberg #8813, 2026-11-11" },
  { id: "uslw-1", book_id: "little-women", place_ids: ["concord-orchard-house"], location: "Chapter 1, Playing Pilgrims", location_zh: "第1章：扮演朝圣者", text_en: "It was a comfortable room, though the carpet was faded and the furniture very plain, for a good picture or two hung on the walls, books filled the recesses, chrysanthemums and Christmas roses bloomed in the windows, and a pleasant atmosphere of home peace pervaded it.", text_zh: "这是一间舒适的屋子，虽然地毯已经褪色，家具也很简朴，墙上却挂着一两幅好画，壁龛里放满书，窗边盛开着菊花和圣诞玫瑰，满屋洋溢着家庭安宁的愉悦气息。", highlight_en: ["comfortable"], translation: "original", status: "draft", checked: "Project Gutenberg #514, 2026-11-11" },
  { id: "usgg-1", book_id: "great-gatsby", place_ids: ["great-neck-west-egg"], location: "Chapter 1", location_zh: "第1章", text_en: "I lived at West Egg, the—well, the less fashionable of the two, though this is a most superficial tag to express the bizarre and not a little sinister contrast between them. My house was at the very tip of the egg, only fifty yards from the Sound, and squeezed between two huge places that rented for twelve or fifteen thousand a season.", text_zh: "我住在西卵，就是两地中不那么时髦的一处——不过，这个说法太肤浅，无法表达两者间古怪而颇为阴森的差别。我家位于卵形半岛最尖的一端，距海湾只有五十码，夹在两座每季租金高达一万二到一万五千的巨宅之间。", highlight_en: ["West Egg"], translation: "original", status: "draft", checked: "Project Gutenberg #64317, 2026-11-11" },
  { id: "usgg-2", book_id: "great-gatsby", place_ids: ["manhattan-plaza-hotel"], location: "Chapter 4", location_zh: "第4章", text_en: "One October day in nineteen-seventeen—\n(said Jordan Baker that afternoon, sitting up very straight on a straight chair in the tea-garden at the Plaza Hotel)\n—I was walking along from one place to another, half on the sidewalks and half on the lawns.", text_zh: "一九一七年十月的一天——那天下午，乔丹·贝克挺直身子坐在广场饭店茶园的一把直背椅上，这样说道——我正从一个地方走向另一个地方，一会儿走在人行道上，一会儿走在草坪上。", highlight_en: ["Plaza Hotel"], translation: "original", status: "draft", checked: "Project Gutenberg #64317, 2026-11-11" },
  { id: "usgb-1", book_id: "gold-bug", place_ids: ["sullivans-island"], location: "Opening, Legrand’s retreat", location_zh: "开篇：勒格朗的隐居处", text_en: "To avoid the mortification consequent upon his disasters, he left New Orleans, the city of his forefathers, and took up his residence at Sullivan's Island, near Charleston, South Carolina.", text_zh: "为了避免遭受厄运后的羞辱，他离开了祖先居住的新奥尔良，搬到南卡罗来纳州查尔斯顿附近的沙利文岛居住。", highlight_en: ["Sullivan's Island"], translation: "original", status: "draft", checked: "Project Gutenberg #2147, 2026-11-11" },
  { id: "usgb-2", book_id: "gold-bug", place_ids: ["charleston-gold-bug"], location: "Opening, the October visit", location_zh: "开篇：十月的拜访", text_en: "Just before sunset I scrambled my way through the evergreens to the hut of my friend, whom I had not visited for several weeks—my residence being, at that time, in Charleston, a distance of nine miles from the island, while the facilities of passage and re-passage were very far behind those of the present day.", text_zh: "日落前，我穿过常青树丛，费力地来到朋友的小屋；我已有几个星期没去看他了。我当时住在查尔斯顿，离岛九英里，而往返交通的便利程度远远不及今天。", highlight_en: ["Charleston"], translation: "original", status: "draft", checked: "Project Gutenberg #2147, 2026-11-11" },
  { id: "usmt-1", book_id: "marrow-of-tradition", place_ids: ["wilmington-wellington"], location: "Chapter 16, Ellis Takes a Trick", location_zh: "第16章：埃利斯赢得一局", text_en: "Twenty years before, Wellington had been the world's greatest shipping port for naval stores. But as the turpentine industry had moved southward, leaving a trail of devastated forests in its rear, the city had fallen to a poor fifth or sixth place in this trade, relying now almost entirely upon cotton for its export business.", text_zh: "二十年前，威灵顿曾是世界上最大的船用物资出口港。可是松节油产业一路南移，身后留下遭毁坏的森林，城市在这项贸易中已跌至第五或第六位，如今出口几乎完全依靠棉花。", highlight_en: ["Wellington"], translation: "original", status: "draft", checked: "Project Gutenberg #11228, 2026-11-11" },
  { id: "uswo-1", book_id: "winesburg-ohio", place_ids: ["clyde-winesburg"], location: "Hands", location_zh: "手", text_en: "Upon the half decayed veranda of a small frame house that stood near the edge of a ravine near the town of Winesburg, Ohio, a fat little old man walked nervously up and down.", text_zh: "在俄亥俄州温斯堡镇附近的一道沟壑边，有一座小木屋；一个矮胖的老人正在它半朽的门廊上，紧张地来回踱步。", highlight_en: ["Winesburg, Ohio"], translation: "original", status: "draft", checked: "Project Gutenberg #416, 2026-11-11" },
  { id: "usnh-s1", kind: "scene", book_id: "new-hampshire", place_ids: ["franconia-frost"], location: "New Hampshire, title poem", location_zh: "标题诗《新罕布什尔》", text_en: "At a film screening in Franconia, the speaker recalls the audience laughing at a tiny nearby town's election tally. The moment becomes a meditation on how larger communities look down on smaller ones.", text_zh: "叙述者回忆在弗兰科尼亚看电影时，观众看到邻近小镇的选举票数而发笑。这一幕引出他对大社区如何轻视小社区的思考。", highlight_en: ["Franconia"], highlight_zh: ["弗兰科尼亚"], status: "draft", fact_source: "https://www.gutenberg.org/ebooks/58611" },
  { id: "useh-1", book_id: "entailed-hat", place_ids: ["princess-anne-entailed-hat"], location: "Chapter 1, Two Hat Wearers", location_zh: "第1章：两个戴帽子的人", text_en: "Princess Anne, as its royal name implies, is an old seat of justice, and gentle-minded town on the Eastern Shore.", text_zh: "安妮公主镇，正如它带有王室意味的名字所示，是东岸一座古老的司法中心，也是一座气质温和的城镇。", highlight_en: ["Princess Anne"], translation: "original", status: "draft", checked: "Project Gutenberg #19146, 2026-11-11" },
  { id: "useh-2", book_id: "entailed-hat", place_ids: ["georgetown-entailed-hat"], location: "Chapter 44, The Death of Patty Cannon", location_zh: "第44章：帕蒂·坎农之死", text_en: "The evidence of Cy James and other cowardly companions in her sins was quickly given, and the procession started through the woods and sands to Georgetown, twelve miles to the eastward, where Patty Cannon was received by all the town, waiting up for her, and the jail immediately closed her in.", text_zh: "赛·詹姆斯和其他胆怯的同伙很快作了证，队伍穿过树林和沙地，向东面十二英里外的乔治敦进发。全镇人熬夜等候帕蒂·坎农的到来，她一到便被关进监狱。", highlight_en: ["Georgetown"], translation: "original", status: "draft", checked: "Project Gutenberg #19146, 2026-11-11" },
  { id: "uslom-1", book_id: "life-on-mississippi", place_ids: ["hannibal"], location: "Chapter 53, My Boyhood's Home", location_zh: "第 53 章《童年的故乡》", text_en: "At seven in the morning we reached Hannibal, Missouri, where my boyhood was spent.", text_zh: "早上七点，我们抵达密苏里州汉尼拔，我的童年就是在那里度过的。", highlight_en: ["Hannibal"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-2", book_id: "life-on-mississippi", place_ids: ["memphis"], location: "Chapter 20, A Catastrophe", location_zh: "第 20 章《一场灾难》", text_en: "Forty of the wounded were placed upon pallets on the floor of a great public hall, and among these was Henry. There the ladies of Memphis came every day, with flowers, fruits, and dainties and delicacies of all kinds, and there they remained and nursed the wounded.", text_zh: "四十名伤员被安置在一座大礼堂地板上的铺位上，亨利也在其中。孟菲斯的女士们每天带来鲜花、水果和各种佳肴，留在这里护理伤员。", highlight_en: ["Memphis"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-4", book_id: "life-on-mississippi", place_ids: ["saint-paul", "new-orleans"], location: "Chapter 60, Speculations and Conclusions", location_zh: "第 60 章《推测与结论》", text_en: "WE reached St. Paul, at the head of navigation of the Mississippi, and there our voyage of two thousand miles from New Orleans ended.", text_zh: "我们到达密西西比河航运的终点圣保罗，从新奥尔良出发的两千英里航程至此结束。", highlight_en: ["St. Paul", "New Orleans"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-6", book_id: "life-on-mississippi", place_ids: ["dubuque"], location: "Chapter 58, On the Upper River", location_zh: "第 58 章《在河流上游》", text_en: "We move up the river—always through enchanting scenery, there being no other kind on the Upper Mississippi—and pass Moline, a center of vast manufacturing industries; and Clinton and Lyons, great lumber centers; and presently reach Dubuque, which is situated in a rich mineral region. The lead mines are very productive, and of wide extent.", text_zh: "我们溯河而上，沿途始终是迷人的风景——密西西比河上游处处如此——经过工业重镇莫林，又经过木材业重镇克林顿与莱昂斯，不久便到达坐落在富矿地区的迪比克。这里的铅矿产量很高，分布也很广。", highlight_en: ["Dubuque"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "usutc-1", book_id: "uncle-toms-cabin", place_ids: ["louisville"], location: "Chapter 22, The Grass Withereth—the Flower Fadeth", location_zh: "第 22 章《草必枯干，花必凋残》", text_en: "It contained various refreshing items of home intelligence, with which our reader is fully acquainted: stated how Aunt Chloe had been hired out to a confectioner in Louisville, where her skill in the pastry line was gaining wonderful sums of money, all of which, Tom was informed, was to be laid up to go to make up the sum of his redemption money; Mose and Pete were thriving, and the baby was trotting all about the house, under the care of Sally and the family generally.", text_zh: "信中有许多令人欣慰的家乡消息，这些读者已经知道：克洛伊大娘受雇于路易斯维尔的一位糖果糕点商，她的糕点手艺赚来了可观的收入，汤姆得知这些钱都将存起来为他赎身；摩西与皮特长得很好，小宝宝也已能在屋里走动，由萨莉和家里人照料。", highlight_en: ["Louisville"], translation: "original", status: "draft", checked: "Project Gutenberg #203, 2026-11-11" },
  { id: "ussc-1", book_id: "sister-carrie", place_ids: ["chicago"], location: "Chapter I. THE MAGNET ATTRACTING: A WAIF AMID FORCES", location_zh: "第 1 章《磁石的吸引：漂泊的孤女》", text_en: "\"Chicago!\" called the brakeman, drawing the word out long. They were under a great shadowy train shed, where the lamps were already beginning to shine out, with passenger cars all about and the train moving at a snail's pace. The people in the car were all up and crowding about the door.", text_zh: "“芝加哥！”列车员拖长声音喊道。他们已驶入巨大而昏暗的站棚，灯火开始亮起，四周都是客车，火车像蜗牛一样缓缓前行。车厢里的人全站了起来，挤到门边。", highlight_en: ["Chicago"], highlight_zh: ["芝加哥"], translation: "original", status: "draft", checked: "Project Gutenberg #233, 2026-11-11" },
  { id: "uslhbw-s1", kind: "scene", book_id: "little-house-in-big-woods", place_ids: ["pepin"], location: "Chapter 9, Going to Town", location_zh: "第 9 章《进城》", text_en: "Laura visits Pepin with her family, sees the lake and explores the unfamiliar sights of the town.", text_zh: "劳拉与家人来到佩平，看见湖泊，探索镇上陌生的新鲜景象。", highlight_en: ["Pepin"], status: "draft", fact_source: "https://www.storychasers.com/big-woods", highlight_zh: ["佩平"] },
  { id: "ustkam-s1", kind: "scene", book_id: "to-kill-a-mockingbird", place_ids: ["monroeville"], location: "Chapter 17", location_zh: "第 17 章", text_en: "In the Maycomb courtroom, Atticus hands Bob Ewell a pen and an envelope and asks him to write his name. The spectators watch Ewell write with his left hand.", text_zh: "在梅科姆法庭上，阿蒂克斯递给鲍勃·尤厄尔一支笔和一个信封，请他写下姓名。旁听者看见尤厄尔用左手书写。", highlight_en: ["Maycomb"], highlight_zh: ["梅科姆"], status: "draft", fact_source: "https://www.bookrags.com/notes/tkm/part17.html" },
  { id: "ustcp-s1", kind: "scene", book_id: "color-purple", place_ids: ["eatonton"], location: "Letter 74, the family dinner", location_zh: "第 74 封信，家庭聚餐", text_en: "At a family dinner in rural Georgia, Shug announces that Celie will leave with her for Memphis. When Albert objects, Celie answers him in front of everyone at the table.", text_zh: "在佐治亚乡村的一次家庭聚餐上，莎格宣布西莉将随她前往孟菲斯。艾伯特出言阻拦，西莉当着全桌人的面回击他。", highlight_en: ["Georgia"], highlight_zh: ["佐治亚"], status: "draft", fact_source: "https://crossref-it.info/textguide/the-color-purple/42/3253" },
  { id: "ussaf-s1", kind: "scene", book_id: "sound-and-fury", place_ids: ["oxford-mississippi"], location: "Part 4, April 8, 1928", location_zh: "第四部分，1928年4月8日", text_en: "Dilsey arrives at the church in Jefferson with Benjy, Frony and Luster. Other worshippers gather around them as the Easter service is about to begin.", text_zh: "迪尔西与班吉、弗罗妮和勒斯特来到杰斐逊的教堂。复活节礼拜即将开始，其他礼拜者也在他们周围聚集。", highlight_en: ["Jefferson"], highlight_zh: ["杰斐逊"], status: "draft", fact_source: "https://faulkner.drupal.shanti.virginia.edu/content/sound-and-fury-292-event" },
  { id: "ustewwg-s1", kind: "scene", book_id: "their-eyes-were-watching-god", place_ids: ["eatonville"], location: "Chapter 10", location_zh: "第 10 章", text_en: "With the Eatonville store nearly empty, Tea Cake takes out the checkerboard and invites Janie to play. She sits opposite him, and he coaches her through the moves.", text_zh: "伊顿维尔的商店几乎没有顾客，茶点拿出跳棋盘，邀珍妮一起下棋。她坐到他对面，听他指点每一步走法。", highlight_en: ["Eatonville"], highlight_zh: ["伊顿维尔"], status: "draft", fact_source: "https://pressbooks.library.torontomu.ca/theireyeswerewatchinggod/chapter/10/" },
  { id: "ustewwg-s2", kind: "scene", book_id: "their-eyes-were-watching-god", place_ids: ["jacksonville"], location: "Chapter 13", location_zh: "第 13 章", text_en: "Tea Cake waits at the Jacksonville station in a blue suit and straw hat. When Janie gets off the train, he takes her straight to a preacher's house to marry.", text_zh: "茶点穿着蓝西装、戴着草帽，在杰克逊维尔车站等候。珍妮一下火车，他便带她直奔牧师家结婚。", highlight_en: ["Jacksonville"], highlight_zh: ["杰克逊维尔"], status: "draft", fact_source: "https://pressbooks.library.torontomu.ca/theireyeswerewatchinggod/chapter/13/" },
  { id: "usnas-s1", kind: "scene", book_id: "in-our-time", place_ids: ["seney"], location: "Big Two-Hearted River, Part 1", location_zh: "《大双心河》第一部", text_en: "Nick steps off the train at Seney and finds that fire has destroyed the town before he heads into the countryside.", text_zh: "尼克在塞尼下火车，发现城镇已被大火毁坏，随后走向郊野。", highlight_en: ["Seney"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Big_Two-Hearted_River", highlight_zh: ["塞尼"] },
  { id: "usnas-s2", kind: "scene", book_id: "in-our-time", place_ids: ["fox-river"], location: "Big Two-Hearted River, Part 2", location_zh: "《大双心河》第二部", text_en: "Wading into the river, Nick releases a small trout; when he moves into a deeper pool, a much larger fish takes the bait and escapes.", text_zh: "尼克涉进河里，把钓到的一条小鳟鱼放回水中；他移到更深的水潭，一条大得多的鱼咬住鱼饵，却逃脱了。", highlight_en: ["river"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Big_Two-Hearted_River", highlight_zh: ["河里"] },
  { id: "usld-s1", kind: "scene", book_id: "lonesome-dove", place_ids: ["fort-smith"], location: "July Johnson’s pursuit", location_zh: "朱莱·约翰逊的追捕", text_en: "After Jake Spoon kills a man in Fort Smith and flees, Sheriff July Johnson sets out to find him.", text_zh: "杰克·斯普恩在史密斯堡杀人后逃走，警长朱莱·约翰逊出发追捕他。", highlight_en: ["Fort Smith"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lonesome_Dove", highlight_zh: ["史密斯堡"] },
  { id: "usld-s2", kind: "scene", book_id: "lonesome-dove", place_ids: ["san-antonio"], location: "Return to Texas", location_zh: "返回得克萨斯", text_en: "Call brings Gus's body back to Texas and buries him near San Antonio, fulfilling his friend's final request.", text_zh: "考尔将格斯的遗体带回得克萨斯，安葬在圣安东尼奥附近，完成朋友最后的嘱托。", highlight_en: ["San Antonio"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lonesome_Dove", highlight_zh: ["圣安东尼奥"] },
  { id: "usri-1", kind: "scene", book_id: "us-little-house-on-the-prairie", place_ids: ["us-independence-ingalls-site"], location: "Chapter 12, Fresh Water to Drink", location_zh: "第12章：新鲜的饮用水", text_en: "At the prairie homesite associated with the Ingalls place near Independence, Laura watches the well rescue: Pa climbs down to secure the unconscious Mr. Scott, then he and Ma turn the windlass to bring their neighbor back into the air.", text_zh: "在以独立城附近英格尔斯旧居为背景的草原家园，劳拉目睹了一场井下救援：爸爸下井给昏迷的斯科特先生系好绳索，随后与妈妈一同转动绞盘，把邻居拉回地面。", highlight_en: ["Independence"], highlight_zh: ["独立城"], status: "draft", fact_source: "https://www.fadedpage.com/books/20200415/html.php" },
  { id: "usri-2", book_id: "roughing-it", place_ids: ["salt-lake-city"], location: "Chapter 13", location_zh: "第13章", text_en: "Seen from one of these dizzy heights, twelve or fifteen miles off, Great Salt Lake City is toned down and diminished till it is suggestive of a child's toy-village reposing under the majestic protection of the Chinese wall.", text_zh: "从十二或十五英里外的一处眩目高地望去，大盐湖城的色彩变得柔和，身形也缩小了，仿佛一座玩具村庄，安卧在中国长城般雄伟的屏障之下。", highlight_en: ["Salt Lake City"], highlight_zh: ["盐湖城"], translation: "original", status: "draft", checked: "Project Gutenberg #3177, 2026-11-11" },
  { id: "usri-3", book_id: "roughing-it", place_ids: ["virginia-city"], location: "Chapter 42", location_zh: "第42章", text_en: "I canvassed the city again and found one wretched old hay truck dragging in from the country. But I made affluent use of it. I multiplied it by sixteen, brought it into town from sixteen different directions, made sixteen separate items out of it, and got up such another sweat about hay as Virginia City had never seen in the world before.", text_zh: "我又在城里四处搜寻，只见一辆破旧的运草车从乡下驶来。我却把它利用得十足：将它变成十六辆，从十六个方向进城，编出十六条新闻，让弗吉尼亚城为干草忙得热火朝天，这可是从未有过的事。", highlight_en: ["Virginia City"], highlight_zh: ["弗吉尼亚城"], translation: "original", status: "draft", checked: "Project Gutenberg #3177, 2026-11-11" },
  { id: "usri-4", book_id: "roughing-it", place_ids: ["honolulu"], location: "Chapter 63", location_zh: "第63章", text_en: "We had an abundance of fruit in Honolulu, of course. Oranges, pine- apples, bananas, strawberries, lemons, limes, mangoes, guavas, melons, and a rare and curious luxury called the chirimoya, which is deliciousness itself.", text_zh: "当然，我们在檀香山有许多水果：橙子、菠萝、香蕉、草莓、柠檬、酸橙、芒果、番石榴、甜瓜，还有一种罕见而奇特的美味，叫作秘鲁番荔枝，简直就是美味本身。", highlight_en: ["Honolulu"], highlight_zh: ["檀香山"], translation: "original", status: "draft", checked: "Project Gutenberg #3177, 2026-11-11" },
  { id: "ustia-1", book_id: "us-steep-trails", place_ids: ["mount-hood"], location: "Chapter 21, The Physical and Climatic Characteristics of Oregon", location_zh: "第21章：俄勒冈的地形与气候特点", text_en: "Looking across the forest, over which the mellow light of the sunset was streaming, I soon discovered the source of my friend's excitement. There stood Mount Hood in all the glory of the alpenglow, looming immensely high, beaming with intelligence, and so impressive that one was overawed as if suddenly brought before some superior being newly arrived from the sky.", text_zh: "望过森林，落日柔和的光正流泻其上，我很快明白朋友为什么如此激动。胡德山矗立在那里，沐浴着壮丽的山巅晚霞，高得不可思议，仿佛闪耀着智慧；那景象令人震撼，仿佛突然置身于一位刚从天空降临的超凡存在面前。", highlight_en: ["Mount Hood"], highlight_zh: ["胡德山"], translation: "original", status: "draft", checked: "Project Gutenberg #326, 2026-11-11" },
  { id: "ustia-2", book_id: "travels-in-alaska", place_ids: ["seattle", "tacoma"], location: "Chapter 1, Puget Sound and British Columbia", location_zh: "第1章，普吉特海湾与不列颠哥伦比亚", text_en: "Seattle was famed for its coal-mines, and claimed to be the coming town of the North Pacific Coast. So also did its rival, Tacoma, which had been selected as the terminus of the much-talked-of Northern Pacific Railway.", text_zh: "西雅图以煤矿闻名，自称将成为北太平洋海岸的新兴重镇。它的对手塔科马也这样宣称；人们议论纷纷的北太平洋铁路已选定那里作为终点。", highlight_en: ["Seattle", "Tacoma"], highlight_zh: ["西雅图", "塔科马"], translation: "original", status: "draft", checked: "Project Gutenberg #7345, 2026-11-11" },
  { id: "ustia-3", book_id: "travels-in-alaska", place_ids: ["wrangell"], location: "Chapter 9, A Canoe Voyage to Northward", location_zh: "第9章，乘独木舟北行", text_en: "I arrived at Wrangell in a canoe with a party of Cassiar miners in October while the icy regions to the northward still burned in my mind.", text_zh: "十月，我与一队卡西亚矿工乘独木舟抵达兰格尔，心中仍热切惦念着北方的冰雪世界。", highlight_en: ["Wrangell"], highlight_zh: ["兰格尔"], translation: "original", status: "draft", checked: "Project Gutenberg #7345, 2026-11-11" },
  { id: "usvir-1", book_id: "virginian", place_ids: ["medicine-bow"], location: "Chapter 1, Enter the Man", location_zh: "第1章，人物登场", text_en: "We had plenty of time to watch this sport, for our train had stopped that the engine might take water at the tank before it pulled us up beside the station platform of Medicine Bow.", text_zh: "我们有充足的时间观看这番较量，因为列车停了下来，让机车先在水塔旁加水，然后才把我们拉到梅迪辛博的站台边。", highlight_en: ["Medicine Bow"], highlight_zh: ["梅迪辛博"], translation: "original", status: "draft", checked: "Project Gutenberg #1298, 2026-11-11" },
  { id: "usmyan-1", book_id: "my-antonia", place_ids: ["lincoln-nebraska"], location: "Book 3, Lena Lingard, Chapter 1", location_zh: "第三卷《莉娜·林加德》，第1章", text_en: "I did not go home for my first summer vacation, but stayed in Lincoln, working off a year's Greek, which had been my only condition on entering the freshman class.", text_zh: "第一个暑假我没有回家，而是留在林肯，补修一整年的希腊语；这是我进入一年级时唯一需要补足的条件。", highlight_en: ["Lincoln"], highlight_zh: ["林肯"], translation: "original", status: "draft", checked: "Project Gutenberg #242, 2026-11-11" },
  { id: "usopion-1", book_id: "o-pioneers", place_ids: ["omaha"], location: "Part 2, Neighboring Fields, Chapter 7", location_zh: "第二部《毗邻的田野》，第7章", text_en: "Marie's father, Albert Tovesky, was one of the more intelligent Bohemians who came West in the early seventies. He settled in Omaha and became a leader and adviser among his people there.", text_zh: "玛丽的父亲阿尔伯特·托韦斯基，是十九世纪七十年代初来到西部的波希米亚人中较有见识的一位。他在奥马哈定居，成为当地同乡的领袖和顾问。", highlight_en: ["Omaha"], highlight_zh: ["奥马哈"], translation: "original", status: "draft", checked: "Project Gutenberg #24, 2026-11-11" },
  { id: "usmtr-1", book_id: "main-travelled-roads", place_ids: ["ordway"], location: "Foreword", location_zh: "前言", text_en: "In the summer of 1887, after having been three years in Boston, and six years absent from my old home in northern Iowa, I found myself with money enough to pay my railway fare to Ordway, South Dakota, where my father and mother were living, and as it cost very little extra to go by way of Dubuque and Charles City, I planned to visit Osage, Iowa, and the farm we had opened on Dry Run prairie in 1871.", text_zh: "一八八七年夏天，我在波士顿住了三年，离开爱荷华北部的旧家也已有六年，终于有钱买车票去南达科他的奥德韦看望父母。绕道迪比克和查尔斯城所费无几，我便打算顺路看看爱荷华的奥塞奇，以及我们一八七一年在德赖兰草原开辟的农场。", highlight_en: ["Ordway"], highlight_zh: ["奥德韦"], translation: "original", status: "draft", checked: "Project Gutenberg #2809, 2026-11-11" },
  { id: "usgow-s1", kind: "scene", book_id: "grapes-of-wrath", place_ids: ["flagstaff"], location: "Chapter 18, crossing the Arizona high country", location_zh: "第18章：穿越亚利桑那高地", text_en: "As the Joads climb toward Flagstaff, short trees give way to taller forest and the cars struggle uphill, steaming. Beyond the summit the road runs out across open plateaus; ahead, water will have to be bought by the gallon.", text_zh: "乔德一家向弗拉格斯塔夫爬升时，低矮树木渐渐变成高大的森林，汽车冒着蒸汽艰难上坡。越过高点，道路伸向开阔的高原；再往前，饮水就得按加仑购买。", highlight_en: ["Flagstaff"], highlight_zh: ["弗拉格斯塔夫"], status: "draft", fact_source: "https://s3.amazonaws.com/scschoolfiles/112/grapes_of_wrath_john_steinbeck2.pdf" },
  { id: "usgow-s2", kind: "scene", book_id: "grapes-of-wrath", place_ids: ["sallisaw"], location: "Chapter 6, the deserted Joad home", location_zh: "第6章：荒废的乔德家", text_en: "Near Sallisaw, Tom and Casy find the Joad house tilted off its foundations and emptied of furniture. Tom realizes that even the neighbors have gone: otherwise someone would have salvaged the useful boards.", text_zh: "在萨利索附近，汤姆和凯西发现乔德家的房屋歪离地基，家具全无。汤姆意识到连邻居也已离开：否则早会有人拆走还能用的木板。", highlight_en: ["Sallisaw"], highlight_zh: ["萨利索"], status: "draft", fact_source: "https://www.litcharts.com/lit/the-grapes-of-wrath/chapter-6" },
  { id: "usgow-s3", kind: "scene", book_id: "grapes-of-wrath", place_ids: ["weedpatch-camp"], location: "Chapter 22, the sanitary unit", location_zh: "第22章：卫生设施", text_en: "In the government camp modeled on Weedpatch, Winfield flushes a toilet and the sudden rush of water alarms him and Ruthie: they think they have broken it. Ma later laughs and explains how it works.", text_zh: "在以威德帕奇为原型的政府营地，温菲尔德按下马桶冲水，突如其来的水声吓坏了他和露西：他们以为弄坏了它。妈妈随后笑着解释了冲水的原理。", highlight_en: ["Weedpatch"], highlight_zh: ["威德帕奇"], status: "draft", fact_source: "https://www.bookrags.com/notes/gow/part22.html" },
  { id: "usotr-s1", kind: "scene", book_id: "on-the-road", place_ids: ["denver"], location: "Part 1, Chapter 6", location_zh: "第一部，第6章", text_en: "Sal's first stop in Denver is Chad King's house. There he learns that Dean and Carlo are also in town, but Chad has not been seeing them; the awkward news makes Sal sense a split among his friends.", text_zh: "萨尔抵达丹佛后，先到查德·金家。他得知迪安和卡洛也在城里，但查德并没有与他们来往；这则尴尬的消息让他察觉朋友之间出现了裂痕。", highlight_en: ["Denver"], highlight_zh: ["丹佛"], status: "draft", fact_source: "https://www.sparknotes.com/lit/ontheroad/section3/" },
  { id: "usotr-s2", kind: "scene", book_id: "on-the-road", place_ids: ["san-francisco"], location: "Part 1, Chapter 11", location_zh: "第一部，第11章", text_en: "Before leaving Mill City, Sal climbs to a canyon rim and looks across San Francisco toward the Pacific. At the continent's western edge, he feels that the only direction left is back east.", text_zh: "离开米尔城前，萨尔爬上峡谷边缘，越过旧金山眺望太平洋。来到大陆西端，他觉得剩下的方向只有返回东方。", highlight_en: ["San Francisco"], highlight_zh: ["旧金山"], status: "draft", fact_source: "https://www.sparknotes.com/lit/ontheroad/section4/" },
  { id: "ustwc-s1", kind: "scene", book_id: "travels-with-charley", place_ids: ["fargo"], location: "Part 3, entering Fargo", location_zh: "第三部：进入法戈", text_en: "Crossing the Red River into Fargo on a fine autumn day, Steinbeck finds himself hemmed in by ordinary traffic: a truck ahead and a Thunderbird behind. The crowded, neon-lit city clashes with the place of blizzards and dust storms he had imagined.", text_zh: "秋日晴天，斯坦贝克跨过红河进入法戈，却被寻常车流夹在中间：前面是卡车，后面是雷鸟轿车。拥挤的街道和霓虹灯，与他想象中饱受暴雪和沙尘侵袭的城市大不相同。", highlight_en: ["Fargo"], highlight_zh: ["法戈"], status: "draft", fact_source: "https://gutenbergcanada.ca/ebooks/steinbeckj-travelswithcharley/steinbeckj-travelswithcharley-00-h.html" },
  { id: "ustwc-s2", kind: "scene", book_id: "travels-with-charley", place_ids: ["billings"], location: "Part 3, buying a hat in Billings", location_zh: "第三部：在比灵斯买帽子", text_en: "In Billings, Steinbeck buys a western hat, giving himself a reason to stay a little longer in Montana. His battered naval cap had been attracting attention so far inland, and he replaces it with a restrained stockman's Stetson.", text_zh: "在比灵斯，斯坦贝克买下一顶西部帽，也给自己一个在蒙大拿多停留片刻的理由。来到远离海岸的内陆，他那顶破旧海军帽格外惹眼，于是换成一顶式样稳重的斯泰森牧人帽。", highlight_en: ["Billings"], highlight_zh: ["比灵斯"], status: "draft", fact_source: "https://gutenbergcanada.ca/ebooks/steinbeckj-travelswithcharley/steinbeckj-travelswithcharley-00-h.html" },
  { id: "usaor-s1", kind: "scene", book_id: "angle-of-repose", place_ids: ["kuna"], location: "Idaho section, Kuna station landscape", location_zh: "爱达荷部分：库纳车站风景", text_en: "At Kuna, the narration pauses as the train's bustle gives way to wind humming in the wires. A stage road and the new railway stretch away in different directions through treeless sage country.", text_zh: "在库纳，叙述停留于列车的喧闹散去、风开始在电线上低吟的一刻。驿车道与新铁轨伸向不同方向，四周是没有树木的蒿草荒原。", highlight_en: ["Kuna"], highlight_zh: ["库纳"], status: "draft", fact_source: "https://rohanmaitzen.com/2014/06/" },
  { id: "usaor-s2", kind: "scene", book_id: "angle-of-repose", place_ids: ["leadville"], location: "Part 4, arrival at the Leadville cabin", location_zh: "第四部：抵达莱德维尔小屋", text_en: "When Susan reaches the cabin in Leadville, she struggles to hide her disappointment at its cramped interior. Frank runs up and explains that the commotion in town came from a hanging, turning her arrival at a new home into an encounter with mining-town violence.", text_zh: "苏珊来到莱德维尔的小屋，看见狭窄的室内，努力掩饰失望。弗兰克跑来，解释说镇上的骚动源于一场绞刑，让她初到新居的一刻与矿镇的暴力相撞。", highlight_en: ["Leadville"], highlight_zh: ["莱德维尔"], status: "draft", fact_source: "https://www.supersummary.com/angle-of-repose/parts-3-4/" },
  { id: "usscl-1", book_id: "scarlet-letter", place_ids: ["us-boston-scarlet-letter"], location: "Chapter 2, The Market-Place", location_zh: "第2章：市场", text_en: "The grass-plot before the jail, in Prison Lane, on a certain summer morning, not less than two centuries ago, was occupied by a pretty large number of the inhabitants of Boston, all with their eyes intently fastened on the iron-clamped oaken door. Amongst any other population, or at a later period in the history of New England, the grim rigidity that petrified the bearded physiognomies of these good people would have augured some awful business in hand.", text_zh: "一个夏日的早晨，距今已不少于两个世纪，监狱巷中牢门前的草地上聚集了许多波士顿居民，他们的目光全都紧盯着铁箍橡木门。若换一群人，或换到新英格兰历史上稍晚的年代，这些蓄须面孔上石头般严酷的神情，必定预示着某种可怕的事情即将发生。", highlight_en: ["Boston", "Prison Lane"], translation: "original", status: "draft", checked: "Project Gutenberg #33, 2026-11-11" },
  { id: "usscl-2", book_id: "scarlet-letter", place_ids: ["us-salem-custom-house"], location: "The Custom-House, introductory sketch", location_zh: "导言：海关大楼", text_en: "The pavement round about the above-described edifice—which we may as well name at once as the Custom-House of the port—has grass enough growing in its chinks to show that it has not, of late days, been worn by any multitudinous resort of business. In some months of the year, however, there often chances a forenoon when affairs move onward with a livelier tread. Such occasions might remind the elderly citizen of that period, before the last war with England, when Salem was a port by itself; not scorned, as she is now, by her own merchants and ship-owners, who permit her wharves to crumble to ruin while their ventures go to swell, needlessly and imperceptibly, the mighty flood of commerce at New York or Boston.", text_zh: "上述建筑——不妨直说，就是本港海关大楼——周围铺路石的缝隙里长着足够多的草，可见近来这里并没有熙攘的生意人踩踏。有些月份，却也偶尔有一个上午，事务的脚步显得轻快些。这时，年长的市民或许会想起上次与英国交战以前，塞勒姆独立成港的岁月；那时它还未遭到自己的商人和船主轻视，不像如今，他们任由码头崩塌，自己的买卖却去为纽约或波士顿的巨大商潮增添微不足道的一滴。", highlight_en: ["Custom-House", "Salem"], translation: "original", status: "draft", checked: "Project Gutenberg #33, 2026-11-11" },
  { id: "usai-1", book_id: "age-of-innocence", place_ids: ["us-ny-academy-of-music"], location: "Chapter 1", location_zh: "第1章", text_en: "On a January evening of the early seventies, Christine Nilsson was singing in Faust at the Academy of Music in New York.\nThough there was already talk of the erection, in remote metropolitan distances \"above the Forties,\" of a new Opera House which should compete in costliness and splendour with those of the great European capitals, the world of fashion was still content to reassemble every winter in the shabby red and gold boxes of the sociable old Academy. Conservatives cherished it for being small and inconvenient, and thus keeping out the \"new people\" whom New York was beginning to dread and yet be drawn to; and the sentimental clung to it for its historic associations, and the musical for its excellent acoustics, always so problematic a quality in halls built for the hearing of music.", text_zh: "十九世纪七十年代初，一个一月的夜晚，克里斯蒂娜·尼尔松正在纽约音乐学院歌剧院演唱《浮士德》。虽然人们已经谈论要在遥远的四十街以北建一座豪华的新歌剧院，与欧洲大都市的剧院争胜，时髦社会仍满足于每年冬季在旧歌剧院破旧的红金包厢里重聚。保守者珍爱它的狭小与不便，因为这样便能挡住纽约既害怕又受其吸引的“新人”；多情的人留恋它的历史，爱乐者则看重它优良的音响——这在专为音乐建造的大厅里，往往反而难以保证。", highlight_en: ["Academy of Music", "New York"], translation: "original", status: "draft", checked: "Project Gutenberg #541, 2026-11-11" },
  { id: "usai-2", book_id: "age-of-innocence", place_ids: ["us-ny-lower-fifth-avenue"], location: "Chapter 12", location_zh: "第12章", text_en: "Old-fashioned New York dined at seven, and the habit of after-dinner calls, though derided in Archer's set, still generally prevailed. As the young man strolled up Fifth Avenue from Waverley Place, the long thoroughfare was deserted but for a group of carriages standing before the Reggie Chiverses' (where there was a dinner for the Duke), and the occasional figure of an elderly gentleman in heavy overcoat and muffler ascending a brownstone doorstep and disappearing into a gas-lit hall.", text_zh: "老派纽约人七点吃晚饭；饭后拜访的习惯虽然受到阿切尔那一圈人的嘲笑，却仍普遍存在。年轻人从韦弗利广场沿第五大道漫步而上，长街几乎空无一人，只有里吉·奇弗斯家门前停着一排马车——那里正为公爵设宴——偶尔有一位穿厚大衣、围着围巾的老先生，走上褐石台阶，消失在煤气灯照亮的门厅里。", highlight_en: ["Fifth Avenue"], translation: "original", status: "draft", checked: "Project Gutenberg #541, 2026-11-11" },
  { id: "usai-3", book_id: "age-of-innocence", place_ids: ["us-ny-lower-fifth-avenue"], location: "Chapter 26", location_zh: "第26章", text_en: "Every year on the fifteenth of October Fifth Avenue opened its shutters, unrolled its carpets and hung up its triple layer of window-curtains.\nBy the first of November this household ritual was over, and society had begun to look about and take stock of itself. By the fifteenth the season was in full blast, Opera and theatres were putting forth their new attractions, dinner-engagements were accumulating, and dates for dances being fixed. And punctually at about this time Mrs. Archer always said that New York was very much changed.", text_zh: "每年十月十五日，第五大道便打开百叶窗，铺开地毯，挂起三层窗帘。到十一月一日，这套家居仪式已经完成，社交界开始环顾四周、检点自身。十五日时，社交季已如火如荼，歌剧院与剧场推出新节目，晚宴邀约不断累积，舞会日期也陆续敲定。每逢这时，阿切尔夫人总会准时感叹，纽约已大大变了。", highlight_en: ["Fifth Avenue", "New York"], translation: "original", status: "draft", checked: "Project Gutenberg #541, 2026-11-11" },
  { id: "usan-ct1", book_id: "american-notes", place_ids: ["us-hartford-dickens"], location: "Chapter 5, Hartford", location_zh: "第5章：哈特福德", text_en: "We tarried here, four days. The town is beautifully situated in a basin of green hills; the soil is rich, well-wooded, and carefully improved. It is the seat of the local legislature of Connecticut, which sage body enacted, in bygone times, the renowned code of 'Blue Laws,' in virtue whereof, among other enlightened provisions, any citizen who could be proved to have kissed his wife on Sunday, was punishable, I believe, with the stocks.", text_zh: "我们在这里停留了四天。城镇优美地坐落在绿丘围成的盆地里，土地肥沃，林木茂盛，经过精心整治。这里是康涅狄格地方议会的所在地；这个贤明的机构在往昔制定了著名的“蓝色法规”，其中开明的条款之一是：凡被证实在星期日亲吻妻子的市民，我相信，都可能受到足枷惩罚。", highlight_en: ["Connecticut"], translation: "original", status: "draft", checked: "Project Gutenberg #675, 2026-11-11" },
  { id: "usan-ct2", book_id: "american-notes", place_ids: ["us-hartford-dickens"], location: "Chapter 5, the Charter Oak and public institutions", location_zh: "第5章：宪章橡树与公共机构", text_en: "In Hartford stands the famous oak in which the charter of King Charles was hidden. It is now inclosed in a gentleman's garden. In the State House is the charter itself. I found the courts of law here, just the same as at Boston; the public institutions almost as good. The Insane Asylum is admirably conducted, and so is the Institution for the Deaf and Dumb.", text_zh: "哈特福德有一棵著名的橡树，查理国王的宪章曾藏在其中。如今它被围在一位绅士的花园里。宪章本身则存放在州议会大楼。我发现这里的法庭与波士顿完全一样，公共机构也几乎一样好。精神病院管理得十分出色，聋哑人教育机构也是如此。", highlight_en: ["Hartford", "State"], translation: "original", status: "draft", checked: "Project Gutenberg #675, 2026-11-11" },
  { id: "usan-ct3", book_id: "american-notes", place_ids: ["us-hartford-dickens"], location: "Chapter 5, an encounter at the Hartford asylum", location_zh: "第5章：哈特福德疗养院中的一次交谈", text_en: "There was one little, prim old lady, of very smiling and good-humoured appearance, who came sidling up to me from the end of a long passage, and with a curtsey of inexpressible condescension, propounded this unaccountable inquiry:\n'Does Pontefract still flourish, sir, upon the soil of England?'\n'He does, ma'am,' I rejoined.\n'When you last saw him, sir, he was—'\n'Well, ma'am,' said I, 'extremely well. He begged me to present his compliments. I never saw him looking better.'", text_zh: "有一位矮小端庄的老妇人，面带笑容、神情和善，从长廊那头侧身走来，行了个带着难以形容的屈尊意味的礼，问了一个莫名其妙的问题：“先生，庞特弗拉克特还在英格兰土地上兴旺地活着吗？”我答道：“是的，夫人。”“您上次见到他时，他——”“他很好，夫人，”我说，“好极了。他托我向您问候。我从没见他气色这样好。”", highlight_en: ["old lady"], translation: "original", status: "draft", checked: "Project Gutenberg #675, 2026-11-11" },
  { id: "usan-ct4", book_id: "american-notes", place_ids: ["us-hartford-dickens"], location: "Chapter 5, the musician at the Hartford asylum", location_zh: "第5章：哈特福德疗养院里的乐手", text_en: "There was another: a young man, whose madness was love and music. After playing on the accordion a march he had composed, he was very anxious that I should walk into his chamber, which I immediately did.\nBy way of being very knowing, and humouring him to the top of his bent, I went to the window, which commanded a beautiful prospect, and remarked, with an address upon which I greatly plumed myself:\n'What a delicious country you have about these lodgings of yours!'\n'Poh!' said he, moving his fingers carelessly over the notes of his instrument: 'Well enough for such an Institution as this!'\nI don't think I was ever so taken aback in all my life.", text_zh: "还有一个年轻人，他的疯狂与爱情和音乐有关。他用手风琴奏完自己写的一首进行曲，急切地请我进他的房间，我立刻照办。我想显得很懂他，也尽量顺着他，便走到窗前，欣赏那里的美景，用自以为高明的方式说：“您这住处周围的乡野真美啊！”“哼！”他漫不经心地拨弄着琴键，“对于这样一所机构来说，也算过得去吧！”我想，我这辈子从没这样错愕过。", highlight_en: ["window", "music"], translation: "original", status: "draft", checked: "Project Gutenberg #675, 2026-11-11" },
  { id: "usan-ct5", book_id: "american-notes", place_ids: ["us-new-haven-dickens"], location: "Chapter 5, New Haven", location_zh: "第5章：纽黑文", text_en: "New Haven, known also as the City of Elms, is a fine town. Many of its streets (as its alias sufficiently imports) are planted with rows of grand old elm-trees; and the same natural ornaments surround Yale College, an establishment of considerable eminence and reputation. The various departments of this Institution are erected in a kind of park or common in the middle of the town, where they are dimly visible among the shadowing trees. The effect is very like that of an old cathedral yard in England; and when their branches are in full leaf, must be extremely picturesque. Even in the winter time, these groups of well-grown trees, clustering among the busy streets and houses of a thriving city, have a very quaint appearance: seeming to bring about a kind of compromise between town and country; as if each had met the other half-way, and shaken hands upon it; which is at once novel and pleasant.", text_zh: "纽黑文又名榆树城，是一座美好的城镇。许多街道栽着成排高大的老榆树，同样的天然装饰也环绕着声誉卓著的耶鲁学院。各院系的建筑坐落在城市中央一片公园或公共绿地般的地方，在树荫里隐约可见，颇像英国古老教堂周围的庭院。枝叶茂盛时，这里一定格外如画。即使在冬天，这些成熟的树木簇拥在繁荣城市的繁忙街道与房屋之间，也显得别致，仿佛城市和乡村达成妥协，各自走到半路，握起了手，新鲜而愉快。", highlight_en: ["New Haven", "Yale"], translation: "original", status: "draft", checked: "Project Gutenberg #675, 2026-11-11" },
  { id: "uslim-1", book_id: "life-in-iron-mills", place_ids: ["us-wheeling-iron-mills"], location: "Opening, the narrator’s window", location_zh: "开篇：叙述者的窗前", text_en: "The idiosyncrasy of this town is smoke. It rolls sullenly in slow folds from the great chimneys of the iron-foundries, and settles down in black, slimy pools on the muddy streets. Smoke on the wharves, smoke on the dingy boats, on the yellow river,—clinging in a coating of greasy soot to the house-front, the two faded poplars, the faces of the passers-by. The long train of mules, dragging masses of pig-iron through the narrow street, have a foul vapor hanging to their reeking sides. Here, inside, is a little broken figure of an angel pointing upward from the mantel-shelf; but even its wings are covered with smoke, clotted and black. Smoke everywhere! A dirty canary chirps desolately in a cage beside me. Its dream of green fields and sunshine is a very old dream,—almost worn out, I think.", text_zh: "这座城镇的特征就是烟。浓烟从炼铁厂的大烟囱里缓慢滚出，在泥泞街道上沉成黑色黏腻的水洼。码头上有烟，肮脏的船上有烟，黄色的河面上有烟；油腻的烟灰贴住屋子的正面、两棵褪色的白杨和行人的脸。长长的骡队拖着生铁穿过窄街，热气腾腾的身体旁悬着污浊的蒸气。屋内壁炉架上，一尊破损的小天使伸手指向上方，连它的翅膀也被烟熏得结块发黑。到处都是烟！我身旁笼中的一只脏金丝雀凄凉地鸣叫。它关于绿野与阳光的梦已很古老，我想，几乎磨损殆尽了。", highlight_en: ["smoke", "town"], translation: "original", status: "draft", checked: "Project Gutenberg #876, 2026-11-11" },
  { id: "usedl-s1", kind: "scene", book_id: "letters-emily-dickinson", place_ids: ["us-amherst-dickinson-museum"], location: "Letter to Louisa Norcross, December 1861, in the 1924 selection", location_zh: "致路易莎·诺克罗斯的信，1861年12月，收入1924年选集", text_en: "At her Amherst home, Dickinson tells Louisa that snow has covered the garden where she picked flowers only days earlier; she watches the surrounding hills change from autumn color to white.", text_zh: "在阿默斯特的家中，狄金森告诉路易莎，前几天还采过花的花园如今已被雪覆盖；她看着四周的山丘从秋日的色彩转为白色。", highlight_en: ["Amherst", "garden"], highlight_zh: ["阿默斯特", "花园"], status: "draft", fact_source: "https://en.wikisource.org/wiki/The_Life_and_Letters_of_Emily_Dickinson/Letters_of_Emily_Dickinson" },
  { id: "us-cw-1", book_id: "us-call-of-the-wild", place_ids: ["us-santa-clara-valley"], location: "Chapter 1, Into the Primitive", location_zh: "第1章：走向原始", text_en: "Buck lived at a big house in the sun-kissed Santa Clara Valley. Judge Miller's place, it was called. It stood back from the road, half hidden among the trees, through which glimpses could be caught of the wide cool veranda that ran around its four sides. The house was approached by gravelled driveways which wound about through wide-spreading lawns and under the interlacing boughs of tall poplars.", text_zh: "巴克住在阳光普照的圣克拉拉谷的一座大宅里，人们称它为米勒法官的庄园。房子远离道路，半掩在树丛中，透过枝叶可以瞥见环绕四面的宽阔凉爽的走廊。通往房子的碎石车道蜿蜒穿过开阔的草坪，伸向高大白杨交错的枝条下。", highlight_en: ["Santa Clara Valley"], highlight_zh: ["圣克拉拉谷"], translation: "original", status: "draft", checked: "Project Gutenberg #215, 2026-11-11" },
  { id: "us-cw-2", book_id: "us-call-of-the-wild", place_ids: ["us-santa-clara-valley"], location: "Chapter 1, Into the Primitive", location_zh: "第1章：走向原始", text_en: "The Judge was at a meeting of the Raisin Growers' Association, and the boys were busy organizing an athletic club, on the memorable night of Manuel's treachery. No one saw him and Buck go off through the orchard on what Buck imagined was merely a stroll. And with the exception of a solitary man, no one saw them arrive at the little flag station known as College Park. This man talked with Manuel, and money chinked between them.", text_zh: "在曼纽尔背叛他的那个难忘的夜晚，法官正在参加葡萄干种植者协会的会议，男孩们忙着组织体育俱乐部。没人看见曼纽尔带着巴克穿过果园，巴克以为不过是去散步。除了一个孤零零的男人，也没人看见他们来到名叫大学公园的小招呼站。那人和曼纽尔交谈，他们之间响起钱币碰撞的声音。", highlight_en: ["College Park"], highlight_zh: ["大学公园"], translation: "original", status: "draft", checked: "Project Gutenberg #215, 2026-11-11" },
  { id: "us-sw-1", book_id: "us-sea-wolf", place_ids: ["san-francisco"], location: "Chapter 1", location_zh: "第1章", text_en: "Not but that I was afloat in a safe craft, for the Martinez was a new ferry-steamer, making her fourth or fifth trip on the run between Sausalito and San Francisco. The danger lay in the heavy fog which blanketed the bay, and of which, as a landsman, I had little apprehension. In fact, I remember the placid exaltation with which I took up my position on the forward upper deck, directly beneath the pilot-house, and allowed the mystery of the fog to lay hold of my imagination.", text_zh: "倒不是说我乘坐的船不安全，因为“马丁内斯号”是艘新渡轮，才第四或第五次往返索萨利托与旧金山之间。危险在于笼罩海湾的浓雾，而我这个陆地上的人对此几乎毫无戒心。事实上，我记得自己走上驾驶室正下方的前部上层甲板时，心中充满平静的欣喜，任由雾的神秘占据我的想象。", highlight_en: ["San Francisco"], highlight_zh: ["旧金山"], translation: "original", status: "draft", checked: "Project Gutenberg #1074, 2026-11-11" },
  { id: "us-rs-1", book_id: "us-rolling-stones", place_ids: ["san-antonio"], location: "A Fog in Santone", location_zh: "圣安东尼奥的雾", text_en: "The purchaser of the morphia wanders into the fog, and at length, finds himself upon a little iron bridge, one of the score or more in the heart of the city, under which the small tortuous river flows. He leans on the rail and gasps, for here the mist has concentrated, lying like a foot-pad to garrote such of the Three Thousand as creep that way.", text_zh: "买了吗啡的年轻人走入雾中，最后来到一座小铁桥上。城中心有二十多座这样的桥，下面是蜿蜒的小河。他倚着栏杆喘气，因为雾气聚集在这里，像个埋伏的拦路强盗，准备扼住那三千名病客中摸索到这里的人的喉咙。", highlight_en: ["iron bridge"], highlight_zh: ["铁桥"], translation: "original", status: "draft", checked: "Project Gutenberg #3815, 2026-11-11" },
  { id: "us-rs-2", book_id: "us-rolling-stones", place_ids: ["san-antonio"], location: "A Fog in Santone", location_zh: "圣安东尼奥的雾", text_en: "Thus Goodall's tempter deserts him. That youth, uncomplaining and uncaring, takes a spell at coughing, and, recovered, wanders desultorily on down the street, the name of which he neither knows nor recks. At a certain point he perceives swinging doors, and hears, filtering between them a noise of wind and string instruments. Two men enter from the street as he arrives, and he follows them in. There is a kind of ante-chamber, plentifully set with palms and cactuses and oleanders. At little marble-topped tables some people sit, while soft-shod attendants bring the beer.", text_zh: "于是，引诱古德尔的人离开了他。年轻人既不抱怨，也不在乎，咳嗽了一阵，缓过气后便漫无目的地沿街走去，街名是什么，他既不知道也不关心。走到一处，他看见两扇弹簧门，听见门缝里传出的管弦乐声。他到门口时正有两人进去，他便跟在后面。里面像是一间前厅，摆满棕榈、仙人掌和夹竹桃。人们坐在大理石面的小桌旁，穿软鞋的侍者送来啤酒。", highlight_en: ["Goodall"], highlight_zh: ["古德尔"], translation: "original", status: "draft", checked: "Project Gutenberg #3815, 2026-11-11" },
  { id: "us-rs-3", book_id: "us-rolling-stones", place_ids: ["us-austin-land-office"], location: "Bexar Scrip No. 2692", location_zh: "贝克萨土地凭证第2692号", text_en: "But even now, when you enter the building, you lower your voice, and time turns backward for you, for the atmosphere which you breathe is cold with the exudation of buried generations.\nThe building is stone with a coating of concrete; the walls are immensely thick; it is cool in the summer and warm in the winter; it is isolated and sombre; standing apart from the other state buildings, sullen and decaying, brooding on the past.", text_zh: "但即使现在，走进这座建筑，你也会放低声音，仿佛时光倒流，因为你呼吸的空气带着逝去世代渗出的寒意。建筑是石砌的，外面覆着混凝土；墙壁极厚，夏凉冬暖。它孤立而阴沉，与其他州政府建筑保持距离，郁郁地衰朽着，沉思着往昔。", highlight_en: ["building"], highlight_zh: ["建筑"], translation: "original", status: "draft", checked: "Project Gutenberg #3815, 2026-11-11" },
  { id: "us-rs-4", book_id: "us-rolling-stones", place_ids: ["us-austin-land-office"], location: "Bexar Scrip No. 2692", location_zh: "贝克萨土地凭证第2692号", text_en: "He turned to the file room, with a dozen or more files in his hands, and accidentally dropped part of them on the floor. As he stooped to pick them up he swiftly thrust Bexar Scrip No. 2692 in the inside breast pocket of his coat.\nThis happened at just half-past four o'clock, and when the file clerk took the files he threw them in a pile in his room, came out and locked the door.\nThe clerks were moving out of the doors in long, straggling lines.\nIt was closing time.", text_zh: "他拿着十来份卷宗转身走向档案室，“不小心”把其中几份掉在地上。弯腰捡拾时，他迅速把贝克萨土地凭证第2692号塞进外套内侧的胸袋。这时恰好是四点半。档案员接过卷宗，随手堆在房内，出来锁上了门。职员们拖着长长的、稀稀落落的队伍走向出口。下班时间到了。", highlight_en: ["Bexar Scrip No. 2692"], highlight_zh: ["贝克萨土地凭证第2692号"], translation: "original", status: "draft", checked: "Project Gutenberg #3815, 2026-11-11" },
  { id: "us-myan-2", book_id: "my-antonia", place_ids: ["us-red-cloud"], location: "Book 1, The Shimerdas, Chapter 1", location_zh: "第一部：希默尔达一家，第1章", text_en: "I had been sleeping, curled up in a red plush seat, for a long while when we reached Black Hawk. Jake roused me and took me by the hand. We stumbled down from the train to a wooden siding, where men were running about with lanterns. I couldn't see any town, or even distant lights; we were surrounded by utter darkness. The engine was panting heavily after its long run. In the red glow from the fire-box, a group of people stood huddled together on the platform, encumbered by bundles and boxes.", text_zh: "到黑鹰镇时，我已经蜷在红色长毛绒座位上睡了很久。杰克把我叫醒，牵起我的手。我们跌跌撞撞地下车，走上木制站台，四周有人提着灯笼奔忙。我看不见镇子，甚至看不到远处的灯火；周围一片漆黑。跑了长路的火车头正沉重地喘息着。炉膛映出的红光里，一群人挤在站台上，身旁堆着包袱和箱子。", highlight_en: ["Black Hawk"], highlight_zh: ["黑鹰镇"], translation: "original", status: "draft", checked: "Project Gutenberg #242, 2026-11-11" },
  { id: "us-dca-1", book_id: "us-death-comes-for-the-archbishop", place_ids: ["us-santa-fe-cathedral"], location: "Book 9, Death Comes for the Archbishop, Chapter 2", location_zh: "第九部：死神来迎接大主教，第2章", text_en: "Father Latour made his last entry into Santa Fé at the end of a brilliant February afternoon; Bernard stopped the horses at the foot of the long street to await the sunset.\nWrapped in his Indian blankets, the old Archbishop sat for a long while, looking at the open, golden face of his Cathedral. How exactly young Molny, his French architect, had done what he wanted! Nothing sensational, simply honest building and good stone-cutting,—good Midi Romanesque of the plainest. And even now, in winter, when the acacia trees before the door were bare, how it was of the South, that church, how it sounded the note of the South!", text_zh: "拉图尔神父最后一次进入圣菲，是在一个灿烂的二月下午将尽时；贝尔纳把马停在长街尽头，等待日落。老主教裹着印第安毯子，久久坐着，注视他那座主教座堂开阔而金色的正面。年轻的法国建筑师莫尔尼多么准确地实现了他的愿望！没有任何炫耀，只有诚实的建筑和精良的石工——最朴素、纯正的法国南部罗马式风格。即使此刻是冬天，门前的洋槐枝叶凋零，那教堂仍然多么具有南方的气息，多么响亮地奏出南方的音调！", highlight_en: ["Santa Fé", "Cathedral"], highlight_zh: ["圣菲", "主教座堂"], translation: "original", status: "draft", checked: "Project Gutenberg #69730, 2026-11-11" },
  { id: "uslom-8", book_id: "life-on-mississippi", place_ids: ["new-orleans"], location: "Chapter 41, The Metropolis of the South", location_zh: "第 41 章《南方的大都会》", text_en: "Similarly, in high-river stage, in the New Orleans region, the water is up to the top of the enclosing levee-rim, the flat country behind it lies low—representing the bottom of a dish—and as the boat swims along, high on the flood, one looks down upon the houses and into the upper windows. There is nothing but that frail breastwork of earth between the people and destruction.", text_zh: "同样，在新奥尔良一带，河水上涨时，水面高达围堤顶部，而后面的平地低伏着，像一只盘子的底部。船在高高的洪水上行驶，人便俯视着房屋，能看进楼上的窗户。在人们与灭顶之灾之间，只有那道脆弱的土堤。", highlight_en: ["New Orleans"], highlight_zh: ["新奥尔良"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-9", book_id: "life-on-mississippi", place_ids: ["new-orleans"], location: "Chapter 41, The Metropolis of the South", location_zh: "第 41 章《南方的大都会》", text_en: "Canal Street was finer, and more attractive and stirring than formerly, with its drifting crowds of people, its several processions of hurrying street-cars, and—toward evening—its broad second-story verandas crowded with gentlemen and ladies clothed according to the latest mode.", text_zh: "运河街比往昔更漂亮，更迷人，也更热闹：人群缓缓流动，几列街车匆忙穿行；到了傍晚，宽阔的二楼阳台上挤满了衣着入时的绅士淑女。", highlight_en: ["Canal Street"], highlight_zh: ["运河街"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-10", book_id: "life-on-mississippi", place_ids: ["usnew-orleans-french-quarter"], location: "Chapter 44, City Sights", location_zh: "第 44 章《城市景象》", text_en: "THE old French part of New Orleans—anciently the Spanish part—bears no resemblance to the American end of the city: the American end which lies beyond the intervening brick business-center. The houses are massed in blocks; are austerely plain and dignified; uniform of pattern, with here and there a departure from it with pleasant effect; all are plastered on the outside, and nearly all have long, iron-railed verandas running along the several stories. Their chief beauty is the deep, warm, varicolored stain with which time and the weather have enriched the plaster. It harmonizes with all the surroundings, and has as natural a look of belonging there as has the flush upon sunset clouds. This charming decoration cannot be successfully imitated; neither is it to be found elsewhere in America.", text_zh: "新奥尔良古老的法国区——更早时的西班牙区——与砖砌商业中心另一侧的美国人街区毫不相像。房屋成片聚集，外观简朴而庄重，式样整齐一致，间或变化一下便格外悦目；外墙都抹了灰泥，几乎家家每层都有长长的铁栏阳台。它们最美的地方，是岁月与风雨赋予灰泥的深沉、温暖而多彩的色泽。这色泽与周遭融为一体，仿佛晚霞染上云层一样自然。如此迷人的装饰无法仿造，在美国其他地方也找不到。", highlight_en: ["old French part of New Orleans"], highlight_zh: ["新奥尔良古老的法国区"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-11", book_id: "life-on-mississippi", place_ids: ["usnew-orleans-west-end"], location: "Chapter 44, City Sights", location_zh: "第 44 章《城市景象》", text_en: "And by-and-bye we reached the West End, a collection of hotels of the usual light summer-resort pattern, with broad verandas all around, and the waves of the wide and blue Lake Pontchartrain lapping the thresholds. We had dinner on a ground-veranda over the water—the chief dish the renowned fish called the pompano, delicious as the less criminal forms of sin.", text_zh: "后来我们来到西区，这里是一片常见的轻巧夏日旅馆，四面围着宽阔的阳台；辽阔湛蓝的庞恰特雷恩湖，波浪轻拍门槛。我们在水面上的底层露台吃晚饭，主菜是名闻遐迩的鲳鲹，那滋味就像罪过较轻的享乐一样美妙。", highlight_en: ["West End"], highlight_zh: ["西区"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "uslom-12", book_id: "life-on-mississippi", place_ids: ["new-orleans"], location: "Chapter 46, Enchantments and Enchanters", location_zh: "第 46 章《魔法与施法者》", text_en: "THE largest annual event in New Orleans is a something which we arrived too late to sample—the Mardi-Gras festivities. I saw the procession of the Mystic Crew of Comus there, twenty-four years ago—with knights and nobles and so on, clothed in silken and golden Paris-made gorgeousnesses, planned and bought for that single night's use; and in their train all manner of giants, dwarfs, monstrosities, and other diverting grotesquerie—a startling and wonderful sort of show, as it filed solemnly and silently down the street in the light of its smoking and flickering torches; but it is said that in these latter days the spectacle is mightily augmented, as to cost, splendor, and variety.", text_zh: "新奥尔良一年一度最大的盛事是狂欢节，可惜我们来得太迟，无缘亲见。二十四年前，我曾在这里看过科穆斯神秘团的游行：骑士、贵族等人身穿巴黎制作的华丽丝绸金饰服装，专为那一夜设计购置；队伍里还有巨人、矮人、怪物及种种有趣的奇形异状。在冒烟、闪烁的火炬光中，队伍庄严而无声地走过街道，真是惊人而奇妙的景象。据说这些年来，游行的花费、华丽程度和种类都大大增加了。", highlight_en: ["New Orleans", "Mardi-Gras"], highlight_zh: ["新奥尔良", "狂欢节"], translation: "original", status: "draft", checked: "Project Gutenberg #245, 2026-11-11" },
  { id: "ussaf-s2", kind: "scene", book_id: "sound-and-fury", place_ids: ["oxford-mississippi"], location: "Part 1, April 7, 1928", location_zh: "第一部分，1928年4月7日", text_en: "At the fence beside the Compson house in Jefferson, Benjy watches golfers moving across the family's former pasture. Their calls to a caddie bring back his distress over Caddy's absence.", text_zh: "在杰斐逊康普生宅邸旁的篱笆边，班吉望着高尔夫球手走过家里昔日的牧场。他们呼唤球童的声音，又勾起了他对凯蒂离去的痛苦。", highlight_en: ["Jefferson"], highlight_zh: ["杰斐逊"], status: "draft", fact_source: "https://faulkner.drupal.shanti.virginia.edu/content/compson-inset-pasturegolf-course-sound-and-fury-location" },
  { id: "ussaf-s3", kind: "scene", book_id: "sound-and-fury", place_ids: ["oxford-mississippi"], location: "Part 1, childhood memory of 1898", location_zh: "第一部分，对1898年童年的回忆", text_en: "At the Compson home in Jefferson, Caddy climbs the tree beside the house to peer into the parlor. Her brothers wait below, looking up at her muddy underwear.", text_zh: "在杰斐逊的康普生家，凯蒂爬上屋旁的树，朝客厅里张望。哥哥弟弟们等在树下，抬头看着她沾满泥的内裤。", highlight_en: ["Jefferson"], highlight_zh: ["杰斐逊"], status: "draft", fact_source: "https://faulkner.drupal.shanti.virginia.edu/content/compson-inset-pear-tree-sound-and-fury-location" },
  { id: "ussaf-s4", kind: "scene", book_id: "sound-and-fury", place_ids: ["oxford-mississippi"], location: "Part 1, April 7, 1928", location_zh: "第一部分，1928年4月7日", text_en: "In the Compson kitchen in Jefferson, Benjy sits facing the fire with his birthday cake. Luster reaches for more cake while Benjy keeps watching the flames.", text_zh: "在杰斐逊康普生家的厨房，班吉拿着生日蛋糕，面朝炉火坐着。勒斯特伸手再拿一块蛋糕，班吉仍盯着火焰。", highlight_en: ["Jefferson"], highlight_zh: ["杰斐逊"], status: "draft", fact_source: "https://faulkner.drupal.shanti.virginia.edu/content/sound-and-fury-57-event-0" },
  { id: "ussaf-s5", kind: "scene", book_id: "sound-and-fury", place_ids: ["oxford-mississippi"], location: "Part 4, April 8, 1928, final carriage ride", location_zh: "第四部分，1928年4月8日，结尾的马车行程", text_en: "When Luster turns the carriage the unfamiliar way around the monument in Jefferson, Benjy begins to bellow. Jason rushes up and makes the horse turn back.", text_zh: "勒斯特驾车绕行杰斐逊纪念碑时走了不同于惯常的方向，班吉便大声吼叫起来。杰生冲上前来，让马掉头回去。", highlight_en: ["Jefferson"], highlight_zh: ["杰斐逊"], status: "draft", fact_source: "https://faulkner.drupal.shanti.virginia.edu/content/sound-and-fury-320-event" },
  { id: "usgwtw-s1", kind: "scene", book_id: "usgone-with-wind", place_ids: ["usatlanta"], location: "Chapter 9", location_zh: "第 9 章", text_en: "At the hospital bazaar in Atlanta, Rhett bids for a dance with Scarlett. Still dressed in mourning, she springs out of the booth and accepts while the room turns to stare.", text_zh: "在亚特兰大的医院义卖会上，瑞德出价邀斯卡莉特跳舞。她仍穿着丧服，却从摊位里跳起身来答应，满屋的人都转头盯着她。", highlight_en: ["Atlanta"], highlight_zh: ["亚特兰大"], status: "draft", fact_source: "https://gutenberg.net.au/ebooks02/0200161.txt" },
  { id: "usgwtw-s2", kind: "scene", book_id: "usgone-with-wind", place_ids: ["usatlanta"], location: "Chapter 17", location_zh: "第 17 章", text_en: "At noon in an Atlanta hospital, Scarlett removes her apron and slips away while Mrs. Merriwether writes a letter for a wounded soldier. She leaves before the next train brings more casualties.", text_zh: "中午，在亚特兰大的一家医院里，梅里韦瑟太太正替一名伤兵写信，斯卡莉特趁机脱下围裙溜走，赶在下一列火车送来更多伤员之前离开。", highlight_en: ["Atlanta"], highlight_zh: ["亚特兰大"], status: "draft", fact_source: "https://gutenberg.net.au/ebooks02/0200161.txt" },
  { id: "usgwtw-s3", kind: "scene", book_id: "usgone-with-wind", place_ids: ["usatlanta"], location: "Chapter 22", location_zh: "第 22 章", text_en: "In the shuttered bedroom in Atlanta, Scarlett fans Melanie with a palmetto leaf during labor. Whenever she drives the flies from Melanie's face, they settle on her feet.", text_zh: "在亚特兰大一间放下窗帘的卧室里，斯卡莉特用棕榈叶给临产的梅兰妮扇风。她刚赶走脸上的苍蝇，苍蝇又落到了梅兰妮脚上。", highlight_en: ["Atlanta"], highlight_zh: ["亚特兰大"], status: "draft", fact_source: "https://gutenberg.net.au/ebooks02/0200161.txt" },
  { id: "usgwtw-s4", kind: "scene", book_id: "usgone-with-wind", place_ids: ["usatlanta"], location: "Chapter 23", location_zh: "第 23 章", text_en: "Rhett arrives at the Atlanta house with a battered little wagon. He refuses to load a trunk and prepares to take Scarlett and the exhausted Melanie out of the city.", text_zh: "瑞德驾着一辆破旧的小马车来到亚特兰大的屋前。他拒绝装上大行李箱，准备带斯卡莉特和筋疲力尽的梅兰妮离开城里。", highlight_en: ["Atlanta"], highlight_zh: ["亚特兰大"], status: "draft", fact_source: "https://gutenberg.net.au/ebooks02/0200161.txt" },
  { id: "ussc-3", book_id: "sister-carrie", place_ids: ["chicago"], location: "Chapter III. WEE QUESTION OF FORTUNE: FOUR-FIFTY A WEEK", location_zh: "第 3 章《命运的小问题：每周四元五角》", text_en: "So severe a defeat told sadly upon her nerves. Her feet carried her mechanically forward, every foot of her progress being a satisfactory portion of a flight which she gladly made. Block after block passed by. Upon streetlamps at the various corners she read names such as Madison, Monroe, La Salle, Clark, Dearborn, State, and still she went, her feet beginning to tire upon the broad stone flagging. She was pleased in part that the streets were bright and clean. The morning sun, shining down with steadily increasing warmth, made the shady side of the streets pleasantly cool. She looked at the blue sky overhead with more realisation of its charm than had ever come to her before.", text_zh: "如此惨重的挫败使她心神沮丧。双脚机械地带着她前进，每走一步，都让她为逃离此地而略感宽慰。她走过一个又一个街区。在街角的路灯上，她读到麦迪逊、门罗、拉萨尔、克拉克、迪尔伯恩、斯泰特等街名，却仍往前走；踏着宽阔的石板路，双脚开始疲乏。街道明亮洁净，多少使她高兴。晨光越来越暖，背阴的一侧因而格外凉爽。她抬头看着蓝天，比从前任何时候都更能体会它的美。", highlight_en: ["Madison"], highlight_zh: ["麦迪逊"], translation: "original", status: "draft", checked: "Project Gutenberg #233, 2026-11-11" },
  { id: "ussc-4", book_id: "sister-carrie", place_ids: ["chicago"], location: "Chapter IV. THE SPENDINGS OF FANCY: FACTS ANSWER WITH SNEERS", location_zh: "第 4 章《幻想的挥霍：事实报以冷笑》", text_en: "It was with weak knees and a slight catch in her breathing that she came up to the great shoe company at Adams and Fifth Avenue and entered the elevator. When she stepped out on the fourth floor there was no one at hand, only great aisles of boxes piled to the ceiling. She stood, very much frightened, awaiting some one.", text_zh: "她双膝发软，呼吸也有些不畅，来到亚当斯街与第五大道交会处的大鞋业公司，走进电梯。到四楼出来时，近旁一个人也没有，只见宽阔过道旁的箱子直堆到天花板。她十分害怕，站在那里等人。", highlight_en: ["Adams and Fifth Avenue"], highlight_zh: ["亚当斯街与第五大道"], translation: "original", status: "draft", checked: "Project Gutenberg #233, 2026-11-11" },
  { id: "ussc-5", book_id: "sister-carrie", place_ids: ["chicago"], location: "Chapter VII. THE LURE OF THE MATERIAL: BEAUTY SPEAKS FOR ITSELF", location_zh: "第 7 章《物质的诱惑：美貌不言自明》", text_en: "Drouet knew a place in Wabash Avenue where there were rooms. He showed Carrie the outside of these, and said: \"Now, you're my sister.\" He carried the arrangement off with an easy hand when it came to the selection, looking around, criticising, opining. \"Her trunk will be here in a day or so,\" he observed to the landlady, who was very pleased.", text_zh: "杜洛埃知道沃巴什大道上有一处房子出租。他带嘉莉看了外面，说：“现在，你是我妹妹。”挑选房间时，他轻松自如，四下察看，评头论足，发表意见。“她的行李箱一两天内就会送来，”他对满心欢喜的女房东说。", highlight_en: ["Wabash Avenue"], highlight_zh: ["沃巴什大道"], translation: "original", status: "draft", checked: "Project Gutenberg #233, 2026-11-11" },
  { id: "ussc-6", book_id: "sister-carrie", place_ids: ["chicago"], location: "Chapter VIII. INTIMATIONS BY WINTER: AN AMBASSADOR SUMMONED", location_zh: "第 8 章《冬日的征兆：使者被召来》", text_en: "They walked north on Wabash to Adams Street and then west. The lights in the stores were already shining out in gushes of golden hue. The arc lights were sputtering overhead, and high up were the lighted windows of the tall office buildings. The chill wind whipped in and out in gusty breaths. Homeward bound, the six o'clock throng bumped and jostled. Light overcoats were turned up about the ears, hats were pulled down. Little shop-girls went fluttering by in pairs and fours, chattering, laughing. It was a spectacle of warm-blooded humanity.", text_zh: "他们沿沃巴什大道向北走到亚当斯街，再转向西。商店灯光已一片片泛出金色的光辉，头顶的弧光灯噼啪作响，高高的办公大楼窗户也亮了。寒风一阵阵呼啸穿行。六点钟归家的人潮推推挤挤；薄大衣的领子竖到耳边，帽子压得低低的。年轻女店员三三两两轻快走过，边说边笑。这是一幅充满热血与生气的人间景象。", highlight_en: ["Wabash", "Adams Street"], highlight_zh: ["沃巴什大道", "亚当斯街"], translation: "original", status: "draft", checked: "Project Gutenberg #233, 2026-11-11" },
  { id: "usamb-1", book_id: "usmagnificent-ambersons", place_ids: ["indianapolis"], location: "Chapter I", location_zh: "第 1 章", text_en: "At the beginning of the Ambersons' great period most of the houses of the Midland town were of a pleasant architecture. They lacked style, but also lacked pretentiousness, and whatever does not pretend at all has style enough. They stood in commodious yards, well shaded by leftover forest trees, elm and walnut and beech, with here and there a line of tall sycamores where the land had been made by filling bayous from the creek.", text_zh: "安伯森家族的鼎盛时期刚开始时，中部这座城镇的大多数住宅都建得宜人。它们没有特别的风格，却也不矫饰；凡是毫不装腔作势的东西，便已自有风格。房子坐落在宽敞的院落里，残留下来的森林树木——榆树、胡桃树和山毛榉——投下浓荫。有些土地是填平溪流的汊湾而成的，那里间或排列着高大的悬铃木。", highlight_en: ["Midland town"], highlight_zh: ["中部这座城镇"], translation: "original", status: "draft", checked: "Project Gutenberg #8867, 2026-11-11" },
  { id: "usts-1", book_id: "ustom-sawyer", place_ids: ["usmark-twain-cave"], location: "Chapter 29", location_zh: "第 29 章", text_en: "The mouth of the cave was up the hillside—an opening shaped like a letter A. Its massive oaken door stood unbarred. Within was a small chamber, chilly as an icehouse, and walled by Nature with solid limestone that was dewy with a cold sweat. It was romantic and mysterious to stand here in the deep gloom and look out upon the green valley shining in the sun.", text_zh: "洞口在山坡上，形状像字母 A。厚重的橡木门敞开着。里面有一间冰窖般寒冷的小石室，四壁是天然的坚实石灰岩，沁着冷汗。站在这深深的幽暗中，望着外面阳光下明亮的绿色山谷，既浪漫又神秘。", highlight_en: ["cave"], highlight_zh: ["洞口"], translation: "original", status: "draft", checked: "Project Gutenberg #74, 2026-11-11" },
  { id: "usts-2", book_id: "ustom-sawyer", place_ids: ["usmark-twain-cave"], location: "Chapter 31", location_zh: "第 31 章", text_en: "Tom found a subterranean lake, shortly, which stretched its dim length away until its shape was lost in the shadows. He wanted to explore its borders, but concluded that it would be best to sit down and rest awhile, first. Now, for the first time, the deep stillness of the place laid a clammy hand upon the spirits of the children.", text_zh: "不一会儿，汤姆发现一个地下湖，昏暗的水面向远处伸展，直到轮廓消失在阴影里。他想沿着湖边探查，却觉得最好先坐下休息片刻。这时，洞中深沉的寂静第一次像一只湿冷的手，按在两个孩子的心头。", highlight_en: ["subterranean lake"], highlight_zh: ["地下湖"], translation: "original", status: "draft", checked: "Project Gutenberg #74, 2026-11-11" },
  { id: "ushf-1", book_id: "ushuckleberry-finn", place_ids: ["hannibal"], location: "Chapter 2", location_zh: "第 2 章", text_en: "Well, when Tom and me got to the edge of the hilltop we looked away down into the village and could see three or four lights twinkling, where there was sick folks, maybe; and the stars over us was sparkling ever so fine; and down by the village was the river, a whole mile broad, and awful still and grand.", text_zh: "我和汤姆到了山顶边缘，往下望着村镇，看见三四点灯光闪烁，也许是有人生了病；头顶的星星亮得真好。村边就是河，足有一英里宽，静得不得了，也壮观得不得了。", highlight_en: ["village"], highlight_zh: ["村镇"], translation: "original", status: "draft", checked: "Project Gutenberg #76, 2026-11-11" },
  { id: "ushf-2", book_id: "ushuckleberry-finn", place_ids: ["usst-louis"], location: "Chapter 12", location_zh: "第 12 章", text_en: "Every night we passed towns, some of them away up on black hillsides, nothing but just a shiny bed of lights; not a house could you see. The fifth night we passed St. Louis, and it was like the whole world lit up. In St. Petersburg they used to say there was twenty or thirty thousand people in St. Louis, but I never believed it till I see that wonderful spread of lights at two o'clock that still night. There warn't a sound there; everybody was asleep.", text_zh: "我们每晚都经过城镇，有些高踞黑沉沉的山坡，看不见房屋，只见一片闪亮的灯火。第五夜经过圣路易斯，仿佛整个世界都点亮了。在圣彼得斯堡，人们常说圣路易斯有两三万人，我一直不信，直到那个寂静的夜晚两点钟，看见那么壮阔的一片灯光。那里一声响动也没有；大家都睡着了。", highlight_en: ["St. Louis"], highlight_zh: ["圣路易斯"], translation: "original", status: "draft", checked: "Project Gutenberg #76, 2026-11-11" }
];
